insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.south-staffordshire.wombourne-north.by.2026-09-24',103119,'https://candidates.democracyclub.org.uk/api/next/people/103119/','Anil Singh','singh','joint-party:53-119','Labour and Co-operative Party',NULL,NULL,NULL,true,'Anil is proud to live in the friendly neighbourhood Lower Penn, close to the wonderful Wombourne village. He passionately beilieves local businesses should take priority for contracts with the local Council.

With very high levels of council tax, huge savings cound be generated by using systems thinking approaches by bringing the pothole fixing team in-house, devolving it to our District Council would create a more responsive service and end the cycle of botched repairs.

His highest priority is to promote ''good neightbours'' across the District. Let''s plant more trees, this will absorb carbon and enable nature to thrive.','2026-09-19T15:51:03Z',1) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.cotswold.blockley.by.2026-09-24',55316,'https://candidates.democracyclub.org.uk/api/next/people/55316/','Tom Bradley','bradley','PP52','Conservative and Unionist Party','Local Conservatives',NULL,NULL,true,'Living in the heart of the division, I’m proud to be standing to be Campden Vale’s councillor. I will always champion our local area, making sure it gets its fair share of resource. I will protect our rural way of life – backing our farmers. And, I will secure extra investment for our local roads.','2026-09-19T15:51:09Z',5) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.cotswold.blockley.by.2026-09-24',77241,'https://candidates.democracyclub.org.uk/api/next/people/77241/','Bob Eastoe','eastoe','PP63','Green Party',NULL,NULL,NULL,true,'“A little about me.
I spent a career in industry with both start-up businesses and multi-nationals. I recently retired as Chief Operating Officer and Chief financial officer of one of Buckinghamshire’s largest manufacturers and private employers. Over the 13 years I was with them we became:
 - the first business of its kind in the world to be carbon neutral over 10 years ago, 
- the first of its kind to achieve ISO Environmental Management accreditation,
- the first business of its kind to use British Red Tractor wool in our product and won a Queen’s Award for Sustainability in 2020. 
During this time, the business more than tripled its turnover and improved its profitability demonstrating that good environmental practice is good business practice.
 
I moved to Moreton-in-Marsh in March 2022 with my wife after having lived in our last village for 32 years where we brought up our three children. It is now time for me to spend my time and expertise supporting those less fortunate than myself and serve our community. I am a volunteer driver for Cotswold friends and I am privileged to have represented the people of Moreton as a town councillor since September 2022.
 
I stood to represent the people, businesses and environment of the new South Cotswolds constituency in the 2024 General Election to ensure meaningful progress on the Climate and Ecology Emergency is taken and that we build a fair and thriving future for us all.
 
I am now standing in the forthcoming Cotswold District Council election for The Rissington''s ward so that the excellent work done by Green Councillor Andrew McLean can be continued. Local democracy will be a big part of the agenda in these elections and I shall ensure peoples'' voices are heard about decisions that affect them in the transition to a new unitary authority and how they can continue to be heard in an ever-centralising political landscape.
 
I am a founder of "Moreton Against Over Development" as I am concerned about the potentially devastating effects this will have on the North Cotswolds, Stow and The Rissingtons.','2026-09-19T15:51:10Z',5) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.cotswold.blockley.by.2026-09-24',39175,'https://candidates.democracyclub.org.uk/api/next/people/39175/','Matt Fincham','fincham','PP7931','Reform UK',NULL,NULL,NULL,true,'Matt Fincham is a public relations consultant and small business owner, a British Army veteran and officer in the Army Reserve. He has lived in the Cotswolds for five years, having grown up in Churchdown, near Gloucester. Matt comes from a farming family and is a strong supporter of farming, countryside industries and the traditional rural way of life. With his rural roots, Matt understands how the needs of people across the Cotswolds differ from cities and aims to champion the views of and issues of Blockley residents and scrutinise council plans to ensure the best outcomes for our area of the Cotswolds.','2026-09-19T15:51:11Z',2) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.cotswold.blockley.by.2026-09-24',119469,'https://candidates.democracyclub.org.uk/api/next/people/119469/','Josh Littler-Jennings','littler-jennings','PP53','Labour Party',NULL,NULL,NULL,false,NULL,NULL,5) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.cotswold.blockley.by.2026-09-24',84194,'https://candidates.democracyclub.org.uk/api/next/people/84194/','Danny Loveridge','loveridge','PP90','Liberal Democrats',NULL,NULL,NULL,true,'I''ve lived in the North Cotswolds for nearly all of my life. It’s my home. I attended St Catherine''s Primary School Chipping Campden School, and I''ve worked in the private sector, for charities and in the public sector.
Whenever I''ve thought about moving away from the area, there have always been things that pull me back: our beautiful countryside, our fantastic local pubs and independent businesses, but most of all, the people.
During this campaign, you''ll hear a lot from other parties about easy fixes and simple solutions. I''m not going to promise those, because I''m tired of politicians pretending they can snap their fingers and fix issues overnight.
What I will promise is to listen carefully, look at the evidence, and give the issues that matter to our community the sensible and measured response they deserve. Whatever decision is ultimately reached, I want it to reflect our community rather than being an easy short term political fix.
This by-election is about who is best placed to serve Blockley and bring people together. I have a plan for our area, whereas Reform want to push their national agenda locally.
• Save our hospital services - As your local district councillor, I will use my position to make standing up for services at North Cotswolds Hospital my number one priority.
• Supporting residents with the cost of living - Many people are feeling the pinch and I will work with officers at the Council to support residents and signpost them to help.
• Hold Thames Water to account.
I hope to meet you on the doorstep over the next few weeks, in the meantime please don’t hesitate to get in touch if you’d like to talk.','2026-09-19T15:51:12Z',2) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.windsor-and-maidenhead.bray.by.2026-09-24',51543,'https://candidates.democracyclub.org.uk/api/next/people/51543/','John Joseph Baldwin','baldwin','PP6810','the Borough first Independents',NULL,NULL,NULL,true,'John has been a dedicated campaigner for Riverside residents for many years. Many of you will remember his work to help save Deerswood Meadow from residential development, including gathering signatures and organising community email campaigns during the frosty February of 2022.

He has consistently scrutinised council decisions and pushed for stronger, fairer planning procedures — work he intends to continue. Riverside residents deserve experienced, independent voices who will act on the issues that matter most.

John looks forward to meeting as many of you as possible in the months ahead and to working for you, and only you, as your local councillor.','2026-09-19T15:51:17Z',1) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
