insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.brighton-and-hove.queens-park.by.2026-09-24',79566,'https://candidates.democracyclub.org.uk/api/next/people/79566/','Rudi Dikty-Daudiyan','dikty-daudiyan','PP90','Liberal Democrats',NULL,NULL,NULL,true,'Brighton and Hove Liberal Democrats are pleased to introduce Rüdi Dikty-Daudiyan as their candidate in the upcoming Queen’s Park by-election.  Rüdi is a freelance translator who is proud to have made his home in the Queen’s Park ward.

Rüdi says, “I couldn’t be happier to have made Brighton my home, but like many of our residents, I’m concerned about how it’s being run.  The current Labour council has a massive majority, and yet, we’re not seeing the results we deserve.  This is the sixth expensive by-election being held since they came into office.  That’s money that could have been spent on improving pavements, dealing with bins and recycling and anti-social behaviour.  If elected, I would focus on getting the basics right.

In his spare time, Rüdi plays for the Queen’s Park Tennis Club and volunteers for the Pug Dog Welfare & Rescue Association.  He lives in the ward with his husband and dog Emma.','2026-09-19T15:51:42Z',5) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.brighton-and-hove.queens-park.by.2026-09-24',139480,'https://candidates.democracyclub.org.uk/api/next/people/139480/','Steve Gladwin','gladwin','PP53','Labour Party',NULL,NULL,NULL,true,'Behind the grand facades around Queen’s Park itself are communities facing some of the worst relative poverty in the city.

That is being felt particularly hard by pensioners and families struggling to pay their bills.

I want to be a councillor who is visible, accessible and focused on the issues that make a real difference to people’s lives.

Mr Gladwin, who retired from the NHS earlier this summer, has pledged to put tackling the cost of living, pensioner poverty, and fuel poverty at the heart of his campaign.

He has also highlighted economic regeneration and support for the wider Brighton and Hove economy as key priorities, drawing on previous experience running a small business.

Mr Gladwin lives in the area and has worked in the NHS for nearly 30 years, including as an executive director at several trusts.

He also has experience in local government and worked as a journalist in Brighton and Hove, serving as political editor for a local newspaper.','2026-09-19T15:51:51Z',0) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
