insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.northumberland.amble.by.2026-10-01',121002,'https://candidates.democracyclub.org.uk/api/next/people/121002/','Warren Ladyman','ladyman','PP7931','Reform UK',NULL,NULL,NULL,true,'Warren Ladyman grew up in Amble. His mother and sister lives here too. He knew and was friends with the previous incumbent, Arty Hume, whose sad passing triggered this by-election. Warren is in tune with local issues, particularly the lack of infrastructure, despite all the new homes being built. He is determined to fight for his constituents for improved GP services to allow patients to be seen locally instead of Hadston or elsewhere. When elected, Warren will join the fight to save money in County Hall through local government efficiencies. Vote for change, vote for Warren, vote Reform 🇬🇧 🗳','2026-09-19T15:53:55Z',1) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.northumberland.amble.by.2026-10-01',120789,'https://candidates.democracyclub.org.uk/api/next/people/120789/','Jenny Richards','richards','PP52','Conservative and Unionist Party','The Conservative Party Candidate',NULL,NULL,false,NULL,NULL,1) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.northumberland.amble.by.2026-10-01',118408,'https://candidates.democracyclub.org.uk/api/next/people/118408/','Amy Spriggs','spriggs','PP53','Labour Party',NULL,NULL,NULL,true,'Amble and the surrounding area mean so much to me. This is the area I love, where I’ve grown up, gone to school, worked and lived all my life. To now have the opportunity to put myself forward to represent the community I call home is something I’m incredibly proud of.

If I’m fortunate enough to be elected, I want to bring a positive, hardworking and constructive approach to the role — listening to local people, getting things done and always putting our communities first.

I also want to build a strong working relationship with councillors in neighbouring wards. Our communities are closely connected, and I believe we achieve far more when we work together as a team rather than allowing ward boundaries to get in the way.

I can’t thank Scott Dickinson enough for his encouragement, support and advice to this point. Having worked alongside Scott over the last five years, I’ve seen first-hand just how much can be achieved through hard work, determination and strong community relationships.

I’m excited for the weeks ahead, to get out there, speak to residents and listen to what matters to you.

Amble is my home. I’m proud of where I come from, and I’d be incredibly proud to have the opportunity to represent it.','2026-09-19T15:53:57Z',1) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
