insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.amber-valley.kilburn-denby-holbrook-horsley.by.2026-10-08',99986,'https://candidates.democracyclub.org.uk/api/next/people/99986/','Edward Hudson Oakenfull','oakenfull','PP18382','Restore Britain',NULL,NULL,NULL,true,'Born in Derby. I am aged 56 years of age and have lived most of my life in Belper and Duffield where attended Ecclesbourne school for my A levels, now living on a farm in Denby.

My early career was as an estate agent working in the local area. The past 15 years I have been self employed as a property developer and investor.

I am passionate about sports and keeping fit, my main sport is tennis where I reached 47 in the seniors over 45''s world rankings and captained England in the Seniors Four Nations competition. Until recently I was a council member for tennis main governing body, STGB. I love walking the amazing trails and footpaths we have in the beautiful Derbyshire Dales.

I have been despairing at how our country has been run for decades and for the love of my community and country decided that I needed to make a stand and will be trying all I can to be elected to represent and improve the lives of all the people in my constituency.','2026-09-19T15:54:04Z',3) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.amber-valley.kilburn-denby-holbrook-horsley.by.2026-10-08',123571,'https://candidates.democracyclub.org.uk/api/next/people/123571/','Bess Saunders','saunders','PP63','Green Party',NULL,NULL,NULL,true,'After decades working in the NHS, Bess has seen first-hand the pressure on our public services. Now she’s ready to stand up for our local communities and make sure residents’ voices are heard.

Bess has been knocking on doors and talking to residents across Kilburn, Denby, Holbrook and Horsley to find out what matters most to residents.

One message has come through loud and clear: people are deeply concerned about development on our countryside — particularly the impact of solar farms, new electricity pylons and housing developments.

🌱 Bess will make sure local people have a strong voice on these issues.
This by-election is your chance to choose a councillor who will listen, speak up and stand up for our communities.

💚 Vote Green on October 8th','2026-09-19T15:54:05Z',1) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.amber-valley.kilburn-denby-holbrook-horsley.by.2026-10-08',119653,'https://candidates.democracyclub.org.uk/api/next/people/119653/','Juliette Nicola Stevens','stevens','PP7931','Reform UK',NULL,NULL,NULL,true,'I am honoured and proud to have been selected by Reform UK to stand in the Amber Valley Borough Council by‑election for the Kilburn, Denby, Holbrook and Horsley ward on 8 October 2026, following the resignation of the previous Conservative Party councillor.

I am Interim Chair of Reform UK Amber Valley Branch, and a serving councillor at Denby Parish Council. With many years of experience fighting for people as a Town, Borough and County Councillor, I really hope that people will support me.  I am a farmer and am very active in the community fighting to stop the loss of our agricultural land due to solar farms and housing on the green belt.

I''ve been campaigning and running drop in sessions to help people to fight against the enormous pylons which threaten our beautiful Amber Valley, and am campaigning for the National Grid to put the supply off shore or underground instead, or along the M1 motorway.

Please support me so I can help protect and improve Kilburn, Denby, Holbrook and Horsley by being a voice for you at Amber Valley Borough Council.','2026-09-19T15:54:05Z',2) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
