insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.lambeth.myatts-fields.by.2026-10-08',125678,'https://candidates.democracyclub.org.uk/api/next/people/125678/','Anya Krycek','krycek','PP110','The Socialist Party of Great Britain','The Socialist Party (GB)',NULL,NULL,true,'Anya Krycek is an Irish-born radical feminist and socialist theoretician who has lived in South London for 21 years, bringing together deep expertise in feminist studies with committed revolutionary politics as a member of the Socialist Party of Great Britain. A regular contributor to The Socialist Standard  she synthesizes radical feminist analysis with impossiblism and orthodox Marxist theory to examine the interconnected systems of patriarchy and capitalism, rejecting reformist approaches in favour of fundamental social transformation. Her political work is grounded in practical community engagement, including hands-on animal rescue volunteering that aligns with her ethical framework a life long strict vegetarian, and she is currently putting these principles into electoral practice as the SPGB candidate for Brixton North in the May 2026 local elections and now candidate for Lambeth July 9th election for Clapham Park, where her two decades of embedded local knowledge inform her advocacy for the ward''s residents','2026-09-19T15:55:15Z',2) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
