insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.lambeth.myatts-fields.by.2026-10-08',36284,'https://candidates.democracyclub.org.uk/api/next/people/36284/','Sonia Winifred','winifred','PP63','Green Party','The Green Party',NULL,NULL,true,'Everyone should have the right to live in a decent home, breathe clean air, and ensure a safer, greener planet for the next generation to enjoy. We need to invest in our communities and create an economy where all voices are listened to. We need change and hope for the future!

But after twenty years as a member of the Labour Party, and ten years as councillor and Lambeth cabinet member for the Equalities and Culture portfolio, I saw communities like mine become invisible to the Labour Party. Our voices weren’t heard.

Thousands of residents petitioned Lambeth Council to vote for a motion calling for a ceasefire in Gaza – but when I refused to vote against the Gaza ceasefire motion that the Greens brought, Labour suspended me.

Lambeth residents deserve better, and they have been ignored for far too long! I joined the Green Party to change that, and since May they’ve begun to change that in Lambeth by listening and inviting the community to have a say in how services are delivered.

I am totally committed to representing the residents of Myatt’s Fields and the challenge of fixing Lambeth’s broken housing and repair systems, empowering our communities, and fighting for people every day.','2026-09-19T15:55:16Z',2) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('parl.holborn-and-st-pancras.by.2026-10-08',84249,'https://candidates.democracyclub.org.uk/api/next/people/84249/','Sagal Abdi-Wali','abdi-wali','PP53','Labour Party',NULL,NULL,NULL,true,'I am delighted that local members have put their trust in me to be Labour’s candidate in the area I’ve grown up in.

This place welcomed my family as refugees and gave us hope when we needed it most. I am so grateful to have had the opportunity to build a life here, serving our community as a councillor, school governor, and community activist. Now I am standing to say thank you and to give back the hope you gave me.

Throughout this campaign, I promise to put our communities at the heart of everything I do, now and for the future. Together, we can make hope win.','2026-09-19T15:55:22Z',2) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
