“We have a distinct, confident liberal message - on housing, on safety, on giving young Londoners like me a fair shot at building a life here - and I''m going to make that case on every doorstep between now and October 8th.”','2026-09-19T15:55:33Z',4) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
