insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.leeds.calverley-farsley.by.2026-10-22',139515,'https://candidates.democracyclub.org.uk/api/next/people/139515/','Daisy Gilpin','gilpin','PP63','Green Party',NULL,NULL,NULL,true,'I’m delighted to have been selected as the Green Party candidate for Calverley and Farsley.

I live in Rodley, have an allotment in Calverley, and spend a lot of time in our green spaces and supporting local businesses. I care deeply about our area and the people who call it home. I’m excited to get out into our communities, listen to residents and ask: “What can I do to help?”

I joined the Green Party because, for the first time in a long time, I felt hopeful about what a different kind of politics could look like. I’m incredibly proud to have the opportunity to contribute, and I can’t wait to get started.','2026-09-19T15:57:28Z',0) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);
insert into candidates (ballot_paper_id,dc_person_id,dc_person_url,name,surname_sort,party_ec_id,party_name_on_ballot,party_description_on_ballot,homepage_url,wikipedia_url,statement_to_voters_present,statement_to_voters,statement_retrieved_at,previous_candidacies_count) values ('local.leeds.calverley-farsley.by.2026-10-22',123678,'https://candidates.democracyclub.org.uk/api/next/people/123678/','Kathryn Sara Penny','penny','joint-party:53-119','Labour and Co-operative Party',NULL,NULL,NULL,true,'I’ve loved living in our community for 11 years and I want to help make it a place where everyone can flourish just as my family and I have. I’m honoured to be a candidate in the local elections in May and it’s been a privilege to speak to so many residents about what matters to them during my campaign.

I’m passionate about road safety, protecting and investing in our green spaces and supporting residents who may be struggling with the cost of living. As a mum and an educator I also care deeply about developing spaces where young people can play, create and build skills.

If elected as your councillor my priorities will be

**Protecting and investing in green spaces** – safeguarding our parks, paths, canal and green belt for future generations.

**Improving road safety** – making our roads safer for pedestrians, cyclists and drivers.

**Creating opportunities for young people** – expanding opportunities and support to give every young person the best possible start in life.

**Supporting residents with cost of living** – standing up for families and pensioners facing rising bills and financial pressure and fighting for investment in public services such as libraries, clean streets and improved transport links.

I really love our community and I want to make it a great place to grow up, work and live. I am not a career politician and I can bring my experience of leadership in my other jobs to represent you with focus and professionalism.

**I want to be your councillor because I have a passion for making the place we call home even better, across all our areas of Calverley, Farsley, Pudsey, Rodley, Stanningley, Thornbury and Woodhall. I’d be grateful for your support.**','2026-09-19T15:57:29Z',1) on conflict (ballot_paper_id,dc_person_id) do update set statement_to_voters=coalesce(excluded.statement_to_voters,candidates.statement_to_voters), statement_to_voters_present=excluded.statement_to_voters_present or candidates.statement_to_voters_present, homepage_url=coalesce(excluded.homepage_url,candidates.homepage_url);